DELIMITER $$
-- 自定义函数: 必须 RETURNS 恰好一个标量, 且不可含事务控制语句
CREATE FUNCTION f_tax(p_salary DECIMAL(10,2))
RETURNS DECIMAL(10,2)
DETERMINISTIC
NO SQL
BEGIN
    RETURN p_salary * 0.10;
END$$

-- 流程控制示例: IF / CASE / WHILE / REPEAT / LOOP
CREATE PROCEDURE p_flow(IN p_n INT, OUT p_sum INT, OUT p_grade CHAR(1))
BEGIN
    DECLARE v_i INT DEFAULT 0;
    SET p_sum = 0;
    WHILE v_i < p_n DO              -- 前测循环: 可能 0 次
        SET v_i = v_i + 1;
        SET p_sum = p_sum + v_i;
    END WHILE;
    REPEAT                          -- 后测循环: 至少 1 次
        SET v_i = v_i - 1;
    UNTIL v_i <= 0 END REPEAT;
    CASE                            -- 搜索 CASE(存储程序语句形态)
        WHEN p_sum >= 90 THEN SET p_grade = 'A';
        WHEN p_sum >= 60 THEN SET p_grade = 'B';
        ELSE SET p_grade = 'F';
    END CASE;
END$$
DELIMITER ;

SELECT f_tax(8000.00) AS tax;       -- 函数出现在表达式位置
